package org.apache.commons.math.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math.FieldElement;
import org.apache.commons.math.exception.NotPositiveException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.apache.commons.math3.exception.NullArgumentException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_divide_TriageGen2Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testDivide_NullArgument() {
        Complex c = new Complex(1.0, 1.0);
        try {
            c.divide(null);
            fail("Expected NullArgumentException");
        } catch (NullArgumentException e) {
            // Success
        }
    }

    @Test
    public void testDivide_NaN_Result() {
        // Case: dividend is NaN
        Complex nanDividend = new Complex(Double.NaN, 1.0);
        Complex divisor = new Complex(1.0, 1.0);
        assertTrue(nanDividend.divide(divisor).isNaN());

        // Case: divisor is NaN
        Complex dividend = new Complex(1.0, 1.0);
        Complex nanDivisor = new Complex(Double.NaN, 1.0);
        assertTrue(dividend.divide(nanDivisor).isNaN());
    }

    @Test
    public void testDivide_DivideByZero() {
        // Case: divisor is (0, 0)
        Complex dividend = new Complex(1.0, 1.0);
        Complex zeroDivisor = new Complex(0.0, 0.0);
        assertTrue(dividend.divide(zeroDivisor).isNaN());
    }

    @Test
    public void testDivide_InfiniteDivisor() {
        // Case: divisor is infinite, dividend is finite
        Complex dividend = new Complex(1.0, 1.0);
        Complex infiniteDivisor = new Complex(Double.POSITIVE_INFINITY, 0.0);
        Complex result = dividend.divide(infiniteDivisor);
        assertEquals(0.0, result.getReal(), EPSILON);
        assertEquals(0.0, result.getImaginary(), EPSILON);
    }

    @Test
    public void testDivide_Branch1_AbsC_LessThan_AbsD() {
        // Case: |c| < |d|
        // divisor = (1, 2) -> c=1, d=2. |1| < |2| is true.
        Complex dividend = new Complex(4.0, 6.0);
        Complex divisor = new Complex(1.0, 2.0);

        // Manual calculation: (4+6i)/(1+2i) = [(4+6i)(1-2i)] / [1^2 + 2^2]
        // = (4 - 8i + 6i - 12i^2) / 5 = (4 + 12 + 6i - 8i) / 5 = (16 - 2i) / 5 = 3.2 - 0.4i
        Complex result = dividend.divide(divisor);

        assertEquals(3.2, result.getReal(), EPSILON);
        assertEquals(-0.4, result.getImaginary(), EPSILON);
    }

    @Test
    public void testDivide_Branch2_AbsC_GreaterEqual_AbsD() {
        // Case: |c| >= |d|
        // divisor = (2, 1) -> c=2, d=1. |2| < |1| is false.
        Complex dividend = new Complex(4.0, 6.0);
        Complex divisor = new Complex(2.0, 1.0);

        // Manual calculation: (4+6i)/(2+1i) = [(4+6i)(2-1i)] / [2^2 + 1^2]
        // = (8 - 4i + 12i - 6i^2) / 5 = (8 + 6 + 8i) / 5 = 14/5 + 8/5i = 2.8 + 1.6i
        Complex result = dividend.divide(divisor);

        assertEquals(2.8, result.getReal(), EPSILON);
        assertEquals(1.6, result.getImaginary(), EPSILON);
    }

    @Test
    public void testDivide_ExactZeroReal() {
        // Testing the edge of the branch logic with c = 0
        // divisor = (0, 1) -> c=0, d=1. |0| < |1| is true.
        Complex dividend = new Complex(1.0, 1.0);
        Complex divisor = new Complex(0.0, 1.0);

        // (1+i)/(i) = (1+i)(-i)/1 = -i - i^2 = 1 - i
        Complex result = dividend.divide(divisor);
        assertEquals(1.0, result.getReal(), EPSILON);
        assertEquals(-1.0, result.getImaginary(), EPSILON);
    }

    @Test
    public void testDivide_ExactZeroImaginary() {
        // Testing the edge of the branch logic with d = 0
        // divisor = (1, 0) -> c=1, d=0. |1| < |0| is false.
        Complex dividend = new Complex(1.0, 1.0);
        Complex divisor = new Complex(1.0, 0.0);

        // (1+i)/1 = 1 + i
        Complex result = dividend.divide(divisor);
        assertEquals(1.0, result.getReal(), EPSILON);
        assertEquals(1.0, result.getImaginary(), EPSILON);
    }
}
